package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.sql.Connection;
import java.time.Instant;
import java.util.*;

/** Bounded projections over durable facts. Captures never grant execution authority. */
public final class ExecutionCapsuleService {
    public static final int MAX_INPUT_BYTES=65536, MAX_REVISIONS=20, MAX_ATTEMPTS=100, MAX_ITERATIONS=100;
    private static final Set<String> TERMINAL=Set.of("COMPLETED","FAILED","CANCELLED");
    private static final Set<String> TERMINAL_ATTEMPTS=Set.of("SUCCESS","FAILED","CANCELLED","TIMED_OUT");
    private final Db db;
    private final DelegationService delegation;
    private DelegationService.Materializer materializer;
    public ExecutionCapsuleService(Db db,DelegationService delegation){this.db=db;this.delegation=delegation;}
    public void bindExecutions(DelegationService.Materializer materializer){this.materializer=Objects.requireNonNull(materializer);}

    public ObjectNode build(String executionId){return db.transaction(t->{
        t.connection().setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);
        return buildWithManager(t.connection(),executionId);
    });}

    public ObjectNode buildWithManager(Connection c,String executionId){
        Db t=Db.on(c);ObjectNode execution=t.one("SELECT * FROM executions WHERE id=?::uuid",executionId);
        if(execution==null)throw new IllegalArgumentException("Execution "+executionId+" does not exist");
        boolean terminal=TERMINAL.contains(Json.text(execution,"status"));ArrayNode warnings=Json.array();
        if(!terminal)warnings.add("Execution is "+Json.text(execution,"status")+"; this is a LIVE point-in-time capture, not a terminal capsule");
        List<ObjectNode> revisions=t.query("SELECT * FROM execution_plan_revisions WHERE \"executionId\"=?::uuid ORDER BY \"revisionNumber\" DESC LIMIT ?",executionId,MAX_REVISIONS);
        int revisionCount=count(t,"SELECT COUNT(*) n FROM execution_plan_revisions WHERE \"executionId\"=?::uuid",executionId);
        if(revisionCount>MAX_REVISIONS)warnings.add("Revisions truncated to "+MAX_REVISIONS+" of "+revisionCount);
        List<ObjectNode> logical=t.query("SELECT id,\"stepId\" FROM step_executions WHERE \"executionId\"=?::uuid",executionId);
        Map<String,String> stepIds=new HashMap<>();logical.forEach(s->stepIds.put(Json.text(s,"id"),Json.text(s,"stepId")));
        List<ObjectNode> attempts=t.query("SELECT * FROM step_attempts WHERE \"executionId\"=?::uuid ORDER BY \"createdAt\" DESC,id DESC LIMIT ?",executionId,MAX_ATTEMPTS);
        int attemptCount=count(t,"SELECT COUNT(*) n FROM step_attempts WHERE \"executionId\"=?::uuid",executionId);
        if(attemptCount>MAX_ATTEMPTS)warnings.add("Attempts truncated to "+MAX_ATTEMPTS+" of "+attemptCount);
        JsonNode input=Json.get(execution,"input");int inputBytes=Json.stringify(input).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;
        if(inputBytes>MAX_INPUT_BYTES){input=Json.object("truncated",true,"bytes",inputBytes,"sha256",Json.hash(input));warnings.add("Input exceeds "+MAX_INPUT_BYTES+" bytes; truncated marker captured");}
        ObjectNode outbox=Json.object();for(ObjectNode row:t.query("SELECT o.status,COUNT(*) n FROM dispatch_outbox o JOIN step_attempts a ON a.id=o.\"stepAttemptId\" WHERE a.\"executionId\"=?::uuid GROUP BY o.status",executionId))outbox.set(Json.text(row,"status"),row.get("n"));
        ObjectNode account=t.one("SELECT * FROM budget_accounts WHERE \"scopeType\"='execution' AND \"scopeId\"=?",executionId);
        ObjectNode snapshot=t.one("SELECT version,hash FROM policy_snapshots ORDER BY \"createdAt\" DESC LIMIT 1");
        int decisionCount=count(t,"SELECT COUNT(*) n FROM policy_decisions WHERE \"executionId\"=?",executionId);
        List<ObjectNode> decisions=t.query("SELECT id,\"actionType\",effect FROM policy_decisions WHERE \"executionId\"=? ORDER BY \"createdAt\",id LIMIT 20",executionId);
        if(decisionCount>decisions.size())warnings.add("Policy decisions truncated to "+decisions.size()+" of "+decisionCount);
        int pending=0,decided=0;for(ObjectNode row:t.query("SELECT status,COUNT(*) n FROM approval_requests WHERE \"executionId\"=? GROUP BY status",executionId)){if("PENDING".equals(Json.text(row,"status")))pending=Json.integer(row,"n",0);else decided+=Json.integer(row,"n",0);}
        ObjectNode graph=delegation.projection(executionId,100,c);
        if(Json.bool(graph,"supervisedTruncated",false))warnings.add("Supervised delegation edges may be truncated");
        if(Json.bool(graph,"observedTruncated",false))warnings.add("Observed delegation edges may be truncated");
        ObjectNode active=execution.hasNonNull("activePlanRevisionId")?t.one("SELECT \"planHash\" FROM execution_plan_revisions WHERE id=?::uuid",execution.get("activePlanRevisionId")):null;
        String inboxJoin=" JOIN step_attempts a ON a.\"invocationId\"=i.\"invocationId\" WHERE a.\"executionId\"=?::uuid";
        ObjectNode header=Json.object("pipelineId",execution.get("pipelineId"),"pipelineVersion",execution.get("pipelineVersion"),"pipelineHash",execution.get("pipelineHash"),"activeRevisionHash",active==null?null:active.get("planHash"),"authorityDeadlineAt",Json.get(execution,"authorityDeadlineAt"),"input",input,"configurationSnapshot",execution.get("configurationSnapshot"),"stepCount",logical.size(),"revisionCount",revisionCount,"attemptCount",attemptCount,"eventCount",count(t,"SELECT COUNT(*) n FROM agent_events WHERE \"executionId\"=?::uuid",executionId),"inboxCount",count(t,"SELECT COUNT(*) n FROM result_inbox i"+inboxJoin,executionId),"conflictCount",count(t,"SELECT COUNT(*) n FROM result_conflicts i"+inboxJoin,executionId),"outbox",outbox,
            "budget",Json.object("account",account==null?null:Json.object("ceilings",account.get("ceilings"),"parentAccountId",Json.get(account,"parentAccountId")),"reservationCount",account==null?0:count(t,"SELECT COUNT(*) n FROM budget_reservations WHERE \"accountId\"=?::uuid",account.get("id"))),
            "policy",Json.object("snapshotVersion",snapshot==null?null:Json.text(snapshot,"version",""),"snapshotHash",snapshot==null?null:snapshot.get("hash"),"decisionCount",decisionCount,"decisions",decisions),"approvals",Json.object("pending",pending,"decided",decided),"delegation",Json.object("supervised",graph.get("supervisedTotal"),"observed",graph.get("observedTotal")),
            "state",Json.object("version",execution.get("executionStateVersion"),"contentHash",Json.hash(execution.hasNonNull("executionState")?execution.get("executionState"):Json.object()),"writeEvidenceCount",count(t,"SELECT COUNT(*) n FROM state_write_evidence WHERE \"executionId\"=?::uuid",executionId)),
            "artifacts",Json.object("producedCount",count(t,"SELECT COUNT(*) n FROM artifacts ar JOIN result_inbox i ON i.id=ar.\"resultInboxId\""+inboxJoin,executionId),"exposureCount",count(t,"SELECT COUNT(*) n FROM artifact_exposures ex JOIN step_attempts a ON a.id=ex.\"stepAttemptId\" WHERE a.\"executionId\"=?::uuid",executionId)));
        ArrayNode revisionProjection=Json.array();for(ObjectNode r:revisions)revisionProjection.add(Json.object("id",r.get("id"),"revisionNumber",r.get("revisionNumber"),"planHash",Json.get(r,"planHash"),"source",r.get("source"),"reason",Json.get(r,"reason"),"validationResult",Json.get(r,"validationResult"),"budget",Json.get(r.path("plan"),"budget"),"steps",r.path("plan").get("steps")));
        ArrayNode attemptProjection=Json.array();for(ObjectNode a:attempts)attemptProjection.add(Json.object("stepId",stepIds.getOrDefault(Json.text(a,"logicalStepId"),Json.text(a,"logicalStepId")),"attemptNumber",a.get("attemptNumber"),"status",a.get("status"),"invocationId",a.get("invocationId"),"planRevisionId",a.get("planRevisionId"),"frozenSpecHash",Json.get(a,"frozenSpecHash"),"executorSnapshot",Json.get(a,"executorSnapshot"),"inputSnapshotHash",a.hasNonNull("inputSnapshot")?Json.hash(a.get("inputSnapshot")):null,"contextSnapshotHash",a.hasNonNull("contextSnapshot")?Json.hash(a.get("contextSnapshot")):null,"efficiency",Json.get(a,"efficiency"),"terminalAt",Json.get(a,"terminalAt"),"error",Json.get(a,"error")));
        ObjectNode capsule=Json.object("schemaVersion","1","executionId",executionId,"capturedAt",Instant.now().toString(),"pointInTime",terminal?"terminal":"live","sourceStatus",execution.get("status"),"contentHash","","header",header,"revisions",revisionProjection,"attempts",attemptProjection,"evidenceCompleteness",warnings);
        ObjectNode run=t.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?::uuid",executionId);
        if(run!=null){List<ObjectNode> iterations=t.query("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=?::uuid ORDER BY \"iterationNumber\" LIMIT ?",run.get("id"),MAX_ITERATIONS);int n=count(t,"SELECT COUNT(*) n FROM coordination_iterations WHERE \"coordinationRunId\"=?::uuid",run.get("id"));if(n>MAX_ITERATIONS)warnings.add("Coordination iterations truncated to "+MAX_ITERATIONS+" of "+n);ArrayNode manifests=Json.array();for(ObjectNode iteration:iterations){int required=0;for(JsonNode worker:iteration.path("workerManifest"))if(Json.bool(worker,"required",false))required++;manifests.add(Json.object("iterationNumber",iteration.get("iterationNumber"),"workerCount",iteration.path("workerManifest").size(),"requiredCount",required,"verifierStepId",Json.get(iteration,"verifierStepId"),"decisionAction",Json.get(iteration.path("decision"),"action"),"decisionHash",Json.get(iteration,"decisionHash"),"outcome",Json.get(iteration,"outcome")));}
            ObjectNode lease=t.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=?::uuid",run.get("id"));ObjectNode handoff=t.one("SELECT \"sourceExecutionId\",\"sourceRunId\",\"bundleHash\",\"createdAt\" FROM handoffs WHERE \"destinationExecutionId\"=?::uuid",executionId);
            capsule.set("coordination",Json.object("run",Json.object("phase",run.get("phase"),"currentIterationNumber",run.get("currentIterationNumber"),"cumulativeWorkers",run.get("cumulativeWorkers"),"config",run.get("config"),"workspace",Json.get(run,"workspace"),"acceptanceEvidence",Json.get(run,"acceptanceEvidence"),"executionWorkspace",lease==null||!lease.hasNonNull("executionPath")?null:Json.object("workspaceExecutionId",lease.get("id"),"mode",lease.get("mode"),"path",lease.get("executionPath"),"baseBranch",Json.get(lease,"baseBranch"),"baseHeadSha",Json.get(lease,"baseHeadSha"),"state",lease.get("state"),"hasUncommittedWork",Json.get(lease,"hasUncommittedWork")),"handoff",handoff),"iterations",manifests));
        }
        capsule.put("contentHash",contentHash(capsule));return capsule;
    }

    /** Global policy display and capture time cannot change a terminal execution's identity. */
    public static String contentHash(ObjectNode capsule){ObjectNode stable=capsule.deepCopy();stable.remove(List.of("capturedAt","contentHash"));ObjectNode policy=(ObjectNode)stable.path("header").path("policy");policy.putNull("snapshotVersion");policy.putNull("snapshotHash");
        // The retained canonicalJson walks Date's enumerable keys ({}), before JSON.stringify's ISO conversion.
        // Preserve that persisted capsule identity while keeping ISO dates on the wire.
        for(JsonNode attempt:stable.path("attempts"))if(attempt.hasNonNull("terminalAt"))((ObjectNode)attempt).set("terminalAt",Json.object());
        return Json.hash(stable);}
    public ObjectNode createExport(String id,String exporter,String note){ObjectNode capsule=build(id);return db.transaction(t->{if(t.one("SELECT id FROM executions WHERE id=?::uuid FOR UPDATE",id)==null)throw new IllegalArgumentException("Execution does not exist");ObjectNode existing=t.one("SELECT * FROM execution_exports WHERE \"executionId\"=?::uuid AND \"capsuleHash\"=?",id,capsule.get("contentHash"));return existing!=null?existing:t.insert("execution_exports",Json.object("executionId",id,"capsuleHash",capsule.get("contentHash"),"exporter",exporter==null?"operator":exporter,"note",note));});}
    public ObjectNode replay(String id,String requester,String note){ObjectNode capsule=build(id);return db.transaction(t->replayWithManager(t.connection(),id,capsule,requester,note));}
    public ObjectNode replayWithManager(Connection c,String id,ObjectNode capsule,String requester,String note){Db t=Db.on(c);ObjectNode resolved=capsule==null?buildWithManager(c,id):capsule;if(!id.equals(Json.text(resolved,"executionId")))throw new IllegalArgumentException("Capsule belongs to another execution");if(!"terminal".equals(Json.text(resolved,"pointInTime")))throw new IllegalArgumentException("Execution "+id+" is "+Json.text(resolved,"sourceStatus")+"; replays require a terminal source");if(!resolved.path("header").hasNonNull("activeRevisionHash"))throw new IllegalArgumentException("Source capsule has no active revision hash");ObjectNode source=t.one("SELECT * FROM executions WHERE id=?::uuid FOR UPDATE",id);if(source==null)throw new IllegalArgumentException("Execution "+id+" is gone");ObjectNode existing=t.one("SELECT * FROM execution_replays WHERE \"sourceExecutionId\"=?::uuid AND \"sourceCapsuleHash\"=?",id,resolved.get("contentHash"));if(existing!=null)return replayResult(existing,resolved);
        ObjectNode revision=t.one("SELECT * FROM execution_plan_revisions WHERE \"executionId\"=?::uuid AND \"planHash\"=?",id,resolved.path("header").get("activeRevisionHash"));if(revision==null)throw new IllegalArgumentException("The active revision is no longer readable");ObjectNode pipeline=Json.object("id",source.get("pipelineId"),"name",source.get("pipelineId"),"version",source.get("pipelineVersion"),"description","Replay of "+id,"contentHash",revision.get("planHash"),"steps",revision.path("plan").get("steps"));if(revision.path("plan").has("budget"))pipeline.set("budget",revision.path("plan").get("budget"));if(materializer==null)throw new IllegalStateException("Replay execution materializer is not bound");ObjectNode target;try{target=materializer.create(c,pipeline,source.get("input"),null);}catch(RuntimeException e){throw e;}catch(Exception e){throw new Db.Failure(e);}ObjectNode replay=t.insert("execution_replays",Json.object("sourceExecutionId",id,"sourceCapsuleHash",resolved.get("contentHash"),"targetExecutionId",target.get("id"),"requester",requester==null?"operator":requester,"note",note));ObjectNode run=t.one("SELECT config FROM coordination_runs WHERE \"executionId\"=?::uuid",id);if(run!=null)t.insert("coordination_runs",Json.object("executionId",target.get("id"),"config",run.get("config"),"phase","PLANNING","currentIterationNumber",0,"cumulativeWorkers",0,"loopDeadlineAt",Instant.now().plusMillis(Json.longValue(run.path("config"),"loopDeadlineMs",0)).toString(),"version",1));return replayResult(replay,resolved);
    }
    private static ObjectNode replayResult(ObjectNode replay,ObjectNode capsule){return Json.object("replay",replay,"capsuleHash",capsule.get("contentHash"),"targetExecutionId",replay.get("targetExecutionId"));}

    public ObjectNode compare(String a,String b){return compareCapsules(build(a),build(b));}
    public static ObjectNode compareCapsules(ObjectNode a,ObjectNode b){Map<String,String> as=stepHashes(a),bs=stepHashes(b),ao=outcomes(a),bo=outcomes(b);Set<String> ids=new TreeSet<>(as.keySet());ids.addAll(bs.keySet());ArrayNode drift=Json.array(),perStep=Json.array(),warnings=Json.array();boolean samePlan=true,sameOutcome=true;for(String id:ids){String ah=as.get(id),bh=bs.get(id),av=ao.get(id),bv=bo.get(id);String pd=ah!=null&&bh!=null?(ah.equals(bh)?"identical":"drifted"):ah!=null?"present_in_a_only":"present_in_b_only";String od=av!=null&&bv!=null?(av.equals(bv)?"same":"drifted"):av==null&&bv==null?"no_evidence_both":av!=null?"no_evidence_b":"no_evidence_a";drift.add(Json.object("stepId",id,"aHash",ah,"bHash",bh,"drift",pd));perStep.add(Json.object("stepId",id,"aStatus",av,"bStatus",bv,"drift",od));samePlan&=pd.equals("identical");sameOutcome&=od.equals("same")||od.equals("no_evidence_both");}
        boolean planUnavailable=warning(a,"Revisions truncated")||warning(b,"Revisions truncated"),live="live".equals(Json.text(a,"pointInTime"))||"live".equals(Json.text(b,"pointInTime")),outcomeUnavailable=live||warning(a,"Attempts truncated")||warning(b,"Attempts truncated");if(planUnavailable)warnings.add("Plan comparison unavailable: revisions were truncated");if(outcomeUnavailable)warnings.add(live?"Outcome comparison unavailable: a source is a LIVE capture":"Outcome comparison unavailable: attempts were truncated");return Json.object("schemaVersion","1","a",Json.object("executionId",a.get("executionId"),"capsuleHash",a.get("contentHash")),"b",Json.object("executionId",b.get("executionId"),"capsuleHash",b.get("contentHash")),"plan",Json.object("identical",samePlan,"unavailable",planUnavailable,"stepDrift",drift),"outcome",Json.object("identical",sameOutcome,"unavailable",outcomeUnavailable,"perStep",perStep),"runtimeClaims",Json.object("aObserved",a.path("header").path("delegation").get("observed"),"bObserved",b.path("header").path("delegation").get("observed")),"warnings",warnings);}
    private static Map<String,String> stepHashes(JsonNode c){Map<String,String> out=new LinkedHashMap<>();JsonNode newest=c.path("revisions").path(0);for(JsonNode s:newest.path("steps"))out.put(Json.text(s,"id"),Json.hash(s));return out;}
    private static Map<String,String> outcomes(JsonNode c){Map<String,String> out=new LinkedHashMap<>();for(JsonNode a:c.path("attempts"))if(TERMINAL_ATTEMPTS.contains(Json.text(a,"status")))out.putIfAbsent(Json.text(a,"stepId"),Json.text(a,"status"));return out;}
    private static boolean warning(JsonNode c,String prefix){for(JsonNode w:c.path("evidenceCompleteness"))if(w.asText().startsWith(prefix))return true;return false;}

    public ObjectNode provenance(String executionId){ObjectNode capsule=build(executionId),graph=delegation.projection(executionId,100,null);ArrayNode nodes=Json.array(),edges=Json.array();Set<String> ids=new HashSet<>();String root="execution:"+executionId;node(nodes,ids,root,"execution",executionId);for(JsonNode r:capsule.path("revisions")){String id="revision:"+Json.text(r,"id");node(nodes,ids,id,"revision","revision "+Json.integer(r,"revisionNumber",0));edge(edges,ids,id,root,"authority");}for(JsonNode a:capsule.path("attempts")){String id="attempt:"+Json.text(a,"invocationId");node(nodes,ids,id,"attempt",Json.text(a,"invocationId"));edge(edges,ids,id,root,"authority");edge(edges,ids,id,"revision:"+Json.text(a,"planRevisionId"),"authority");}if(capsule.path("header").path("budget").hasNonNull("account")){node(nodes,ids,"budget:"+executionId,"budget_account","execution budget account");edge(edges,ids,"budget:"+executionId,root,"authority");}for(JsonNode d:capsule.path("header").path("policy").path("decisions")){String id="policy:"+Json.text(d,"id");node(nodes,ids,id,"policy_decision",Json.text(d,"actionType")+" "+Json.text(d,"effect"));edge(edges,ids,id,root,"authority");}for(JsonNode child:graph.path("supervised")){String id="delegation:"+Json.text(child,"childExecutionId");node(nodes,ids,id,"delegation_child",Json.text(child,"requestId"));edge(edges,ids,root,id,"authority");}for(JsonNode observation:graph.path("observed")){String id="claim:"+Json.text(observation,"observationId");node(nodes,ids,id,"delegation_observation",Json.text(observation,"observationId"));edge(edges,ids,root,id,"claim");}for(ObjectNode exposure:db.query("SELECT ex.* FROM artifact_exposures ex JOIN step_attempts a ON a.id=ex.\"stepAttemptId\" WHERE a.\"executionId\"=?::uuid ORDER BY ex.\"createdAt\",ex.id LIMIT 100",executionId)){String id="exposure:"+Json.text(exposure,"id");node(nodes,ids,id,"artifact_exposure",Json.text(exposure,"artifactId"));edge(edges,ids,root,id,"exposure");}return Json.object("schemaVersion","1","executionId",executionId,"nodes",nodes,"edges",edges);}
    private static void node(ArrayNode nodes,Set<String> ids,String id,String kind,String label){if(ids.contains(id)||nodes.size()>=200)return;ids.add(id);nodes.add(Json.object("id",id,"kind",kind,"label",label));}
    private static void edge(ArrayNode edges,Set<String> ids,String from,String to,String kind){if(edges.size()<500&&ids.contains(from)&&ids.contains(to))edges.add(Json.object("from",from,"to",to,"kind",kind));}

    public ObjectNode projectTelemetry(String executionId){ObjectNode capsule=build(executionId);String trace=Json.sha256(executionId).substring(0,32),root=Json.sha256("execution:"+executionId).substring(0,16);ArrayNode spans=Json.array();boolean failed="FAILED".equals(Json.text(capsule,"sourceStatus"));ObjectNode status=Json.object("code",failed?2:1);if(failed)status.set("message",capsule.get("sourceStatus"));spans.add(span(trace,root,null,"pipeline.execute",1,status,attributes("tenvyr.executionId",executionId,"tenvyr.sourceStatus",Json.text(capsule,"sourceStatus"),"tenvyr.pipelineHash",Json.text(capsule.path("header"),"pipelineHash"),"tenvyr.pointInTime",Json.text(capsule,"pointInTime"))));for(JsonNode a:capsule.path("attempts")){if(spans.size()>=101)break;if(!TERMINAL_ATTEMPTS.contains(Json.text(a,"status")))continue;spans.add(span(trace,Json.sha256("attempt:"+Json.text(a,"invocationId")).substring(0,16),root,"step.execute",3,Json.object("code","SUCCESS".equals(Json.text(a,"status"))?1:2,"message",a.get("status")),attributes("tenvyr.attempt",Json.text(a,"attemptNumber"),"tenvyr.stepId",Json.text(a,"stepId"),"tenvyr.agent",Json.text(a.path("executorSnapshot"),"agent",""),"tenvyr.executorKind",Json.text(a.path("executorSnapshot"),"kind",""),"tenvyr.invocationId",Json.text(a,"invocationId"))));}for(JsonNode child:delegation.projection(executionId,100,null).path("supervised")){if(spans.size()>=101)break;spans.add(span(trace,Json.sha256("child:"+Json.text(child,"childExecutionId")).substring(0,16),root,"delegation.execute",2,Json.object("code",1),attributes("tenvyr.childExecutionId",Json.text(child,"childExecutionId"),"tenvyr.delegationRequestId",Json.text(child,"requestId"),"tenvyr.requestedAgent",Json.text(child,"requestedAgent"))));}return Json.object("resourceSpans",Json.array(Json.object("resource",Json.object("attributes",attributes("service.name","tenvyr-orchestrator","tenvyr.capsuleHash",Json.text(capsule,"contentHash"))),"scopeSpans",Json.array(Json.object("scope",Json.object("name","tenvyr.execution"),"spans",spans)))));}
    private static ObjectNode span(String trace,String id,String parent,String name,int kind,ObjectNode status,ArrayNode attrs){return Json.object("traceId",trace,"spanId",id,"parentSpanId",parent,"name",name,"kind",kind,"startTimeUnixNano","0","endTimeUnixNano","0","status",status,"attributes",attrs);}
    private static ArrayNode attributes(String... pairs){ArrayNode out=Json.array();for(int i=0;i<pairs.length;i+=2)out.add(Json.object("key",pairs[i],"value",Json.object("stringValue",pairs[i+1])));return out;}
    private static int count(Db t,String sql,Object... args){return Json.integer(t.one(sql,args),"n",0);}
}
